const rtdal004362Source0005 = `test_that("Trigonometric system solves correctly with global='dbldog'", {
  znlm <- nleqslv(
    xstart,
    trig,
    global = "dbldog",
    control = list(trace = 0)
  )

  # Convergence checks
  expect_equal(znlm$termcd, 1)
  expect_equal(znlm$message, "Function criterion near zero")

  # Residual check
  expect_true(all(abs(znlm$fvec) <= 1e-8))

  znlm <- nleqslv(
    xstart,
    trig,
    trigjac,
    global = "dbldog",
    control = list(trace = 0)
  )

  # Convergence checks
  expect_equal(znlm$termcd, 1)
  expect_equal(znlm$message, "Function criterion near zero")

  # Residual check
  expect_true(all(abs(znlm$fvec) <= 1e-8))
})`

