const rtdal004378Source0065 = `corARMA <-
  ## Constructor for the corARMA class
  function(value = double(p + q), form = ~ 1, p = 0, q = 0, fixed = FALSE)
{
  if (!(p >= 0 && (p == round(p)))) {
    stop("autoregressive order must be a non-negative integer")
  }
  if (!(q >= 0 && (q == round(q)))) {
    stop("moving average order must be a non-negative integer")
  }
  if (0 == (p + q)) {
    stop("at least one of 'p' and 'q' must be > 0")
  }
  if (length(value) != p + q) {
    stop("initial value for parameter of wrong length")
  }
  if (max(abs(value)) >= 1) {
    stop("parameters in ARMA structure must be < 1 in absolute value")
  }
  ## unconstrained parameters
  value <- .C(ARMA_unconstCoef,
	      as.integer(p),
	      as.integer(q),
	      pars = as.double(value))$pars
  attributes(value) <- list(formula = form, p = p, q = q, fixed = fixed)
  class(value) <- c("corARMA", "corStruct")
  value
}`

const rtdal004378Source0066 = `corFactor.corARMA <-
  function(object, ...)
{
    maxLag <- attr(object, "maxLag")
    if(is.null(maxLag)) stop("'object' has not been Initialize()d")
  corD <- Dim(object)
  val <- .C(ARMA_factList,
	    as.double(as.vector(object)),
	    as.integer(attr(object, "p")),
	    as.integer(attr(object, "q")),
	    as.integer(unlist(attr(object, "covariate"))),
	    as.integer(attr(object, "maxLag")),
	    as.integer(unlist(corD)),
	    factor = double(corD[["sumLenSq"]]),
	    logDet = double(1))[c("factor", "logDet")]
  lD <- val[["logDet"]]
  val <- val[["factor"]]
  attr(val, "logDet") <- lD
  val
}`

const rtdal004378Source0067 = `corMatrix.corARMA <-
  function(object, covariate = getCovariate(object), corr = TRUE, ...)
{
  corD <- Dim(object,
	      if(is.list(covariate)) {
		if (is.null(names(covariate)))
		  names(covariate) <- seq_along(covariate)
		rep(names(covariate), lengths(covariate))
	      } else
		rep(1, length(covariate)))
  p <- attr(object, "p")
  q <- attr(object, "q")
  maxLag <- attr(object, "maxLag")
  if(is.null(maxLag)) stop("'object' has not been Initialize()d")
  if (corr) {
    val <- .C(ARMA_matList,
	      as.double(as.vector(object)),
	      as.integer(p),
	      as.integer(q),
	      as.integer(unlist(covariate)),
	      as.integer(maxLag),
	      as.integer(unlist(corD)),
	      mat = double(corD[["sumLenSq"]]))[["mat"]]
    lD <- NULL
  } else {
    val <- .C(ARMA_factList,
              as.double(as.vector(object)),
              as.integer(attr(object, "p")),
              as.integer(attr(object, "q")),
              as.integer(unlist(covariate)),
              as.integer(attr(object, "maxLag")),
              as.integer(unlist(corD)),
              factor = double(corD[["sumLenSq"]]),
              logDet = double(1))[c("factor", "logDet")]
    lD <- val[["logDet"]]
    val <- val[["factor"]]
  }
  if (corD[["M"]] > 1) {
    val <- split(val, rep(1:corD[["M"]], (corD[["len"]])^2))
    val <- lapply(val, function(el) {
      nel <- round(sqrt(length(el)))
      array(el, c(nel, nel))
    })
    names(val) <- names(corD[["len"]])
    val <- as.list(val)
  } else {
    val <- array(val, c(corD[["N"]], corD[["N"]]))
  }
  attr(val, "logDet") <- lD
  val
}`

const rtdal004378Source0068 = `coef.corARMA <-
  function(object, unconstrained = TRUE, ...)
{
  if (attr(object, "fixed") && unconstrained) {
    return(numeric(0))
  }
  val <-  as.vector(object)
  if (!unconstrained) {
    p <- attr(object, "p")
    q <- attr(object, "q")
    nams <- NULL
    if (p > 0) {
      nams <- paste(rep("Phi", p), 1:p, sep="")
    }
    if (q > 0) {
      nams <- c(nams, paste(rep("Theta", q), 1:q, sep=""))
    }
    val <- c(.C(ARMA_constCoef, as.integer(attr(object,"p")),
		as.integer(attr(object,"q")),
		pars = as.double(val))$pars)
    names(val) <- nams
  }
  val
}`

const rtdal004378Source0069 = "`coef<-.corARMA` <- function(object, ..., value)\n{\n  maxLag <- attr(object, \"maxLag\")\n  if(is.null(maxLag)) stop(\"'object' has not been Initialize()d\")\n  if (length(value) != length(object)) {\n    stop(\"cannot change the length of the parameter of a \\\"corARMA\\\" object\")\n  }\n  p <- attr(object, \"p\")\n  q <- attr(object, \"q\")\n  object[] <- value\n  ## updating the factor list and logDet\n  corD <- Dim(object)\n  aux <- .C(ARMA_factList,\n\t    as.double(as.vector(object)),\n\t    as.integer(p),\n\t    as.integer(q),\n\t    as.integer(unlist(getCovariate(object))),\n\t    as.integer(attr(object, \"maxLag\")),\n\t    as.integer(unlist(corD)),\n\t    factor = double(corD[[\"sumLenSq\"]]),\n\t    logDet = double(1))[c(\"factor\", \"logDet\")]\n  attr(object, \"factor\") <- aux[[\"factor\"]]\n  attr(object, \"logDet\") <- -aux[[\"logDet\"]]\n  object\n}"

const rtdal004378Source0070 = `Initialize.corARMA <-
  function(object, data, ...)
{
  ## Initializes corARMA objects
  object <- NextMethod()
  covar <- attr(object, "covariate")
  if(!is.list(covar)) covar <- list(covar)
  covar <- lapply(covar, as.integer)
  if (any(lapply(covar, anyDuplicated) > 0)) {
    stop("covariate must have unique integer values within groups for \"corARMA\" objects")
  }
  p <- attr(object, "p")
  q <- attr(object, "q")
  if (p == 1 && q == 0 && all(unlist(lapply(covar, diff)) == 1)) {
    ## Use AR1 methods instead
    class(object) <- c("corAR1", "corStruct")
    Initialize(object, data)
  } else {
    maxLag <- max(unlist(lapply(covar, function(el) diff(range(el)))))
    if (p > maxLag || q > maxLag) {
      stop(gettextf("\"corARMA\" order (%g, %g) exceeds maximum lag in data (%g)",
                    p, q, maxLag), domain = NA)
    }
    attr(object, "maxLag") <- maxLag
    attr(object, "factor") <- corFactor(object)
    attr(object, "logDet") <- -attr(attr(object, "factor"), "logDet")
    object
  }
}`

