const rtdal004378Source0076 = `coef.corCompSymm <-
  function(object, unconstrained = TRUE, ...)
{
  if (unconstrained) {
    if (attr(object, "fixed")) {
      return(numeric(0))
    } else {
      return(as.vector(object))
    }
  }
  val <- exp(as.vector(object))
  val <- c((val + attr(object, "inf"))/(val + 1))
  names(val) <- "Rho"
  val
}`

const rtdal004378Source0077 = "`coef<-.corCompSymm` <- function(object, ..., value)\n{\n  if (length(value) != length(object)) {\n    stop(\"cannot change the length of the parameter of a \\\"corCompSymm\\\" object\")\n  }\n  object[] <- value\n  corD <- attr(object, \"Dim\")\n  ## updating the factor list and logDet\n  aux <- .C(compSymm_factList,\n\t    as.double(as.vector(object)),\n\t    as.double(attr(object, \"inf\")),\n\t    as.integer(unlist(corD)),\n\t    factor = double(corD[[\"sumLenSq\"]]),\n\t    logDet = double(1))[c(\"factor\", \"logDet\")]\n  attr(object, \"factor\") <- aux[[\"factor\"]]\n  attr(object, \"logDet\") <- -aux[[\"logDet\"]]\n  object\n}"

const rtdal004378Source0078 = `Initialize.corCompSymm <-
  ## Initializes corCompSymm objects
  function(object, data, ...)
{
  if (!is.null(attr(object, "inf"))) {   # initialized - nothing to do
    return(object)
  }
  object <- NextMethod()
  natPar <- as.vector(object)
  corD <- Dim(object)
  if (natPar <= (attr(object, "inf") <- -1/(corD[["maxLen"]] - 1))) {
      stop(gettextf("initial value in \"corCompSymm\" must be greater than %s",
                    attr(object, "inf")), domain = NA)
  }
  object[] <- log((natPar - attr(object, "inf"))/(1 - natPar))
  attr(object, "factor") <- corFactor(object)
  attr(object, "logDet") <- -attr(attr(object, "factor"), "logDet")
  object
}`

