const rtdal004449Source0001 = `as.list.key <- function(x, ...){
  key <- x
  pubkey <- derive_pubkey(key)
  pk <- as.list(pubkey)
  list(
    type = pk$type,
    size = pk$size,
    pubkey = pubkey,
    data = decompose(key)
  )
}`

