const rtdal004498Source0001 = "friendly_type <- local({\n  friendly_type <- function(x, value = TRUE, length = FALSE) {\n    if (is_missing(x)) {\n      return(\"absent\")\n    }\n\n    if (is.object(x)) {\n      if (inherits(x, \"quosure\")) {\n        return(\"a <quosure> object\")\n      } else if (identical(class(x), \"data.frame\")) {\n        return(\"a data frame\")\n      } else if (identical(class(x), c(\"tbl_df\", \"tbl\", \"data.frame\"))) {\n        return(\"a tibble\")\n      } else {\n        # this is sometimes wrong for 'h', but ce la vie\n        fst <- tolower(substr(class(x)[1], 1, 1))\n        prop <- if (fst %in% c(\"a\", \"e\", \"i\", \"o\", \"u\")) {\n          \"an\"\n        } else {\n          \"a\"\n        }\n        return(paste0(prop, \" <\", class(x)[1], \"> object\"))\n      }\n    }\n\n    if (!is_vector(x)) {\n      return(as_friendly_type(typeof(x)))\n    }\n\n    n_dim <- length(dim(x))\n\n    if (value && !n_dim) {\n      if (is_na(x)) {\n        return(switch(\n          typeof(x),\n          logical = \"`NA`\",\n          integer = \"an integer `NA`\",\n          double = \"a numeric `NA`\",\n          complex = \"a complex `NA`\",\n          character = \"a character `NA`\",\n          typeof(x)\n        ))\n      }\n      if (length(x) == 1 && !is_list(x)) {\n        return(switch(\n          typeof(x),\n          logical = if (x) \"`TRUE`\" else \"`FALSE`\",\n          integer = \"an integer\",\n          double = \"a number\",\n          complex = \"a complex number\",\n          character = if (nzchar(x)) \"a string\" else \"`\\\"\\\"`\",\n          raw = \"a raw value\",\n          sprintf(\"a %s value\", typeof(x))\n        ))\n      }\n      if (length(x) == 0) {\n        return(switch(\n          typeof(x),\n          logical = \"an empty logical vector\",\n          integer = \"an empty integer vector\",\n          double = \"an empty numeric vector\",\n          complex = \"an empty complex vector\",\n          character = \"an empty character vector\",\n          raw = \"an empty raw vector\",\n          list = \"an empty list\",\n          sprintf(\"a %s of length one\", typeof(x))\n        ))\n      }\n    }\n\n    type <- friendly_vector_type(typeof(x), n_dim)\n\n    if (length && !n_dim) {\n      type <- paste0(type, sprintf(\" of length %s\", length(x)))\n    }\n\n    type\n  }\n\n  friendly_vector_type <- function(type, n_dim) {\n    if (type == \"list\") {\n      if (n_dim < 2) {\n        return(\"a list\")\n      } else if (n_dim == 2) {\n        return(\"a list matrix\")\n      } else {\n        return(\"a list array\")\n      }\n    }\n\n    type <- switch(\n      type,\n      logical = \"a logical %s\",\n      integer = \"an integer %s\",\n      numeric = ,\n      double = \"a double %s\",\n      complex = \"a complex %s\",\n      character = \"a character %s\",\n      raw = \"a raw %s\",\n      type = paste0(\"a \", type, \" %s\")\n    )\n\n    if (n_dim < 2) {\n      kind <- \"vector\"\n    } else if (n_dim == 2) {\n      kind <- \"matrix\"\n    } else {\n      kind <- \"array\"\n    }\n    sprintf(type, kind)\n  }\n\n  as_friendly_type <- function(type) {\n    switch(\n      type,\n\n      list = \"a list\",\n\n      NULL = \"NULL\",\n      environment = \"an environment\",\n      externalptr = \"a pointer\",\n      weakref = \"a weak reference\",\n      S4 = \"an S4 object\",\n\n      name = ,\n      symbol = \"a symbol\",\n      language = \"a call\",\n      pairlist = \"a pairlist node\",\n      expression = \"an expression vector\",\n\n      char = \"an internal string\",\n      promise = \"an internal promise\",\n      ... = \"an internal dots object\",\n      any = \"an internal `any` object\",\n      bytecode = \"an internal bytecode object\",\n\n      primitive = ,\n      builtin = ,\n      special = \"a primitive function\",\n      closure = \"a function\",\n\n      type\n    )\n  }\n\n  is_missing <- function(x) {\n    missing(x) || identical(x, quote(expr = ))\n  }\n\n  is_vector <- function(x) {\n    t <- typeof(x)\n    t %in%\n      c(\n        \"logical\",\n        \"integer\",\n        \"double\",\n        \"complex\",\n        \"character\",\n        \"raw\",\n        \"list\"\n      )\n  }\n\n  is_scalar_vector <- function(x) {\n    is_vector(x) && length(x) == 1L\n  }\n\n  is_na <- function(x) {\n    is_scalar_vector(x) && is.na(x)\n  }\n\n  is_list <- function(x) {\n    typeof(x) == \"list\"\n  }\n\n  list(\n    .internal = environment(),\n    friendly_type = friendly_type\n  )\n})"

