const rtdal004506Source0003 = `msg <- function(message, .envir = parent.frame()) {
  if ("cli" %in% loadedNamespaces()) {
    cli::cli_alert_info(message, .envir = .envir)
  }
}`

const rtdal004506Source0005 = `glob_filter <- function(x, include = NULL, exclude = NULL) {
  if (is.null(include)) {
    res <- x
  } else {
    res <- character()
    for (pat in include) {
      res <- c(res, grep(utils::glob2rx(pat), x, value = TRUE))
    }
    res <- unique(res)
  }
  for (pat in exclude) {
    res <- setdiff(
      res,
      grep(utils::glob2rx(pat), res, value = TRUE)
    )
  }
  res
}`

const rtdal004506Source0006 = "get_env_count <- function(var, default) {\n  strval <- Sys.getenv(var)\n  if (tolower(strval) == \"inf\") {\n    return(Inf)\n  }\n  intval <- suppressWarnings(as.integer(strval))\n  if (!is.na(intval) && intval >= 0) {\n    return(intval)\n  }\n  if (default == Inf) {\n    return(Inf)\n  }\n  intval <- suppressWarnings(as.integer(default))\n  if (!is.na(intval) && intval >= 0) {\n    return(intval)\n  }\n  stop(\n    \"Invalid `default` in `get_env_count()`, must be a non-negative \",\n    \"integer scalar.\"\n  )\n}"

