const rtdal004536Source0023 = `probe <- function(.x, .p, ...) {
  if (is_logical(.p)) {
    stopifnot(length(.p) == length(.x))
    .p
  } else {
    map_lgl(.x, .p, ...)
  }
}`

const rtdal004536Source0024 = `keep <- function(.x, .f, ...) {
  .x[probe(.x, .f, ...)]
}`

const rtdal004536Source0025 = `discard <- function(.x, .p, ...) {
  sel <- probe(.x, .p, ...)
  .x[is.na(sel) | !sel]
}`

const rtdal004536Source0026 = `map_if <- function(.x, .p, .f, ...) {
  matches <- probe(.x, .p)
  .x[matches] <- map(.x[matches], .f, ...)
  .x
}`

