const rtdal004538Source0001 = `ctl_colonnade <- function(x, has_row_id = TRUE, width = NULL,
                          controller = new_tbl(), focus = NULL) {
  "!!!!DEBUG ctl_colonnade()"

  x <- new_data_frame(x, names = names2(x))
  width <- get_width_print(width)

  stopifnot(all(focus %in% names(x)))

  n <- nrow(x)
  nc <- ncol(x)

  if (n == 0 || nc == 0) {
    return(new_colonnade_body(list(), extra_cols = x, abbrev_cols = character(), abbrev_col_idxs = numeric()))
  }

  if (is_false(has_row_id)) {
    rowid <- NULL
  } else {
    rowid <- ctl_new_rowid_pillar(controller, x, width,
      title = NULL,
      type = if (isTRUE(has_row_id)) NULL else has_row_id
    )
  }

  # Reserve space for rowid column in each tier
  if (is.null(rowid)) {
    rowid_width <- 0L
  } else {
    rowid_width <- get_width(rowid)
  }

  has_star <- identical(has_row_id, "*")

  # FIXME: Support for Inf?
  tier_widths <- get_tier_widths(width, nc, rowid_width + 1L)

  formatted_tiers <- list()
  extra_cols <- list(a = 1)[0]
  abbrev_cols <- character()
  abbrev_col_idxs <- numeric()

  on_tier <- function(formatted) {
    # writeLines(formatted)
    formatted_tiers <<- c(formatted_tiers, list(formatted))
  }

  on_extra_cols <- function(my_extra_cols) {
    # print(extra_cols)

    new_extra_cols <- pmap(my_extra_cols, function(x, title, cols) {
      out <- as.list(x)[cols]
      if (is.null(title)) {
        return(out)
      }

      if (length(out) > 1) {
        title_empty <- rep_along(title, "")
        new_names <- paste0(paste0(title_empty, "$", collapse = ""), names(out))
        new_names[[1]] <- paste0(paste0(title, "$", collapse = ""), names(out)[[1]])
        names(out) <- new_names
      } else {
        # Also account for the case of packed matrices here
        names(out) <- prepare_title(c(title, names(out)))
      }
      out
    })

    # Called at most once:
    stopifnot(length(extra_cols) == 0)
    extra_cols <<- unlist(new_extra_cols, recursive = FALSE)
  }

  on_abbrev_col <- function(title) {
    abbrev_cols <<- c(abbrev_cols, title)
  }

  on_get_n_abbrev_cols <- function() {
    length(abbrev_cols)
  }

  cb <- new_emit_tiers_callbacks(
    controller, rowid, rowid_width, has_star,
    on_tier, on_extra_cols, on_abbrev_col, on_get_n_abbrev_cols
  )

  # Side effect: populate formatted_tiers, extra_cols, and abbrev_cols
  do_emit_tiers(x, tier_widths, length(focus), cb, focus)

  new_colonnade_body(formatted_tiers, extra_cols, abbrev_cols, abbrev_col_idxs)
}`

const rtdal004538Source0003 = "do_emit_tiers <- function(x, tier_widths, n_focus, cb, focus) {\n  formatted_list <- NULL\n  extra_cols <- data_frame(x = list(), title = list(), cols = list())\n\n  on_start_tier <- function() {\n    # message(\"on_start_tier()\")\n    formatted_list <<- list()\n  }\n\n  on_end_tier <- function() {\n    # message(\"on_end_tier()\")\n    if (length(formatted_list) > 0) {\n      if (!is.null(cb$rowid)) {\n        formatted_list <- c(list(pillar_format_parts_2(cb$rowid, cb$rowid_width)), formatted_list)\n      }\n\n      aligned <- map(formatted_list, `[[`, \"aligned\")\n\n      tier <- format_colonnade_tier_2(aligned, bidi = get_pillar_option_bidi())\n\n      cb$on_tier(tier)\n    }\n    formatted_list <<- NULL\n  }\n\n  on_pillar <- function(formatted) {\n    # message(\"pillar()\")\n    # print(formatted)\n    # print(pillar, width = width)\n    formatted_list <<- c(formatted_list, list(formatted))\n  }\n\n  on_extra_cols <- function(x, title, cols) {\n    # message(\"extra_cols()\")\n    # print(title)\n    # print(cols)\n    new_extra_cols <- data_frame(\n      x = list(x), title = list(title), cols = list(cols)\n    )\n    # Add to the back, extra columns are emitted in order:\n    extra_cols <<- vec_rbind(extra_cols, new_extra_cols)\n  }\n\n  cb_pillars <- new_emit_pillars_callbacks(\n    cb$controller,\n    on_start_tier = on_start_tier,\n    on_end_tier = on_end_tier,\n    on_pillar = on_pillar,\n    on_top_level_pillar = function(...) {},\n    on_extra_cols = on_extra_cols,\n    on_abbrev_col = cb$on_abbrev_col,\n    on_get_n_abbrev_cols = cb$on_get_n_abbrev_cols\n  )\n\n  # Side effect: populate `extra_cols`,\n  # aggregate and forward calls to higher-level callbacks in `cb`\n  emit_pillars(x, tier_widths, cb_pillars, focus)\n\n  cb$on_extra_cols(extra_cols)\n}"

const rtdal004538Source0005 = `emit_pillars <- function(x, tier_widths, cb, focus) {
  cb$on_start_tier()
  do_emit_focus_pillars(x, tier_widths, cb, focus)
  cb$on_end_tier()
}`

const rtdal004538Source0006 = "do_emit_focus_pillars <- function(x, tier_widths, cb, focus) {\n  stopifnot(is.data.frame(x))\n\n  focus <- sort(match(focus, names(x)))\n  # Shortcut\n  if (length(focus) == 0) {\n    do_emit_pillars(x, tier_widths, cb)\n    return()\n  }\n\n  focus_formatted_list <- list()\n  focus_top_level_end_idx <- integer()\n  focus_extra_cols <- list()\n\n  on_focus_pillar <- function(formatted) {\n    # message(\"pillar()\")\n    # print(formatted)\n    # print(pillar, width = width)\n    focus_formatted_list <<- c(focus_formatted_list, list(formatted))\n  }\n\n  on_focus_top_level_pillar <- function() {\n    focus_top_level_end_idx <<- c(focus_top_level_end_idx, length(focus_formatted_list))\n  }\n\n  on_focus_extra_cols <- function(x, title, cols) {\n    # message(\"extra_cols()\")\n    # print(title)\n    # print(cols)\n    new_extra_cols <- data_frame(x = list(x), title = list(title), cols = list(cols))\n    n_focus_formatted_list <- length(focus_formatted_list)\n\n    if (n_focus_formatted_list <= length(focus_extra_cols)) {\n      focus_extra_cols[[n_focus_formatted_list]] <<- vec_rbind(focus_extra_cols[[n_focus_formatted_list]], new_extra_cols)\n    } else {\n      focus_extra_cols[[n_focus_formatted_list]] <<- new_extra_cols\n    }\n  }\n\n  cb_focus <- new_emit_pillars_callbacks(\n    controller = cb$controller,\n    on_start_tier = function(...) {},\n    on_end_tier = function(...) {},\n    on_pillar = on_focus_pillar,\n    on_top_level_pillar = on_focus_top_level_pillar,\n    on_extra_cols = on_focus_extra_cols,\n    on_abbrev_col = cb$on_abbrev_col,\n    on_get_n_abbrev_cols = cb$on_get_n_abbrev_cols\n  )\n\n  # Side effect: populates focus_formatted_list and focus_extra_cols\n  do_emit_pillars(x[focus], tier_widths, cb_focus, is_focus = TRUE)\n\n  # Can't show focus pillars that don't fit, but need to iterate\n  # to emit extra columns in the correct order\n  length(focus_extra_cols) <- length(focus)\n  n_focus_shown <- length(focus_top_level_end_idx)\n\n  before_start_idx <- vec_lag(focus + 1L, default = 1L)\n  before_end_idx <- focus - 1L\n\n  focus_top_level_start_idx <- vec_lag(focus_top_level_end_idx + 1L, default = 1L)\n\n  # Apply similar strategy as in do_emit_pillars(), but ensure that\n  # focus pillars are shown\n  widths_focus <- map_int(focus_formatted_list, `[[`, \"max_extent\")\n  rev <- distribute_pillars_rev(widths_focus, tier_widths)\n  stopifnot(!anyNA(rev$tier))\n\n  # This indicates the limit until which we expand non-focus column\n  # before the current focus column:\n  rev$offset_before <- pmax(rev$offset_after - rev$width - 1L, 0L)\n  rev_before <- rev[focus_top_level_start_idx, ]\n  stopifnot(nrow(rev_before) == n_focus_shown)\n\n  # This indicates how far the current focus column (with all sub-pillars)\n  # can extend. We use it for convenience to use the same logic as\n  # do_emit_pillars().\n  rev_after <- rev[focus_top_level_end_idx, ]\n  stopifnot(nrow(rev_after) == n_focus_shown)\n\n  x_pos <- 0L\n  tier_pos <- 1L\n\n  for (col in seq_along(focus)) {\n    # Emit extra columns for focus pillars before processing non-focus pillars,\n    # to keep extra columns in order between focus and non-focus pillars:\n    my_extra_cols <- focus_extra_cols[[col]]\n    for (extra_cols_row in seq_len(NROW(my_extra_cols))) {\n      cb$on_extra_cols(\n        my_extra_cols$x[[extra_cols_row]],\n        my_extra_cols$title[[extra_cols_row]],\n        my_extra_cols$cols[[extra_cols_row]]\n      )\n    }\n\n    start <- before_start_idx[[col]]\n    end <- before_end_idx[[col]]\n\n    # Emit non-focus pillars that fit: use offset_before\n    if (start <= end) {\n      sub_tier_widths <- compute_sub_tier_widths(\n        tier_widths, x_pos, tier_pos,\n        rev_before$offset_before[[col]], rev_before$tier[[col]]\n      )\n\n      adv <- advance_emit_pillars(x_pos, tier_pos, x[seq2(start, end)], sub_tier_widths, cb)\n      x_pos <- adv$x_pos\n      tier_pos <- adv$tier_pos\n    }\n\n    # Emit already formatted focus pillar(s):\n    if (col <= length(focus_top_level_start_idx)) {\n      focus_pillars <- seq2(focus_top_level_start_idx[[col]], focus_top_level_end_idx[[col]])\n    } else {\n      focus_pillars <- integer()\n    }\n\n    for (focus_pillar in focus_pillars) {\n      # Deduct widths: use offset_after\n      sub_tier_widths <- compute_sub_tier_widths(\n        tier_widths, x_pos, tier_pos,\n        rev_after$offset_after[[col]], rev_after$tier[[col]]\n      )\n\n      used <- compute_used_width(sub_tier_widths, widths_focus[[focus_pillar]])\n\n      if (used$tiers > 0) {\n        cb$on_end_tier()\n        cb$on_start_tier()\n      }\n\n      cb$on_pillar(focus_formatted_list[[focus_pillar]])\n\n      adv <- advance_pos(x_pos, tier_pos, used)\n      x_pos <- adv$x_pos\n      tier_pos <- adv$tier_pos\n    }\n  }\n\n  # Emit pillars after focus pillar\n  if (length(focus) > 0) {\n    start <- focus[[length(focus)]] + 1L\n  } else {\n    start <- 1L\n  }\n  end <- length(x)\n\n  # Emit non-focus pillars that fit: use offset_before\n  if (start <= end) {\n    sub_tier_widths <- compute_sub_tier_widths(\n      tier_widths, x_pos, tier_pos,\n      tier_widths[[length(tier_widths)]], length(tier_widths)\n    )\n\n    adv <- advance_emit_pillars(x_pos, tier_pos, x[seq2(start, end)], sub_tier_widths, cb)\n    x_pos <- adv$x_pos\n    tier_pos <- adv$tier_pos\n  }\n}"

const rtdal004538Source0007 = `advance_emit_pillars <- function(x_pos, tier_pos, ...) {
  used <- do_emit_pillars(...)
  advance_pos(x_pos, tier_pos, used)
}`

const rtdal004538Source0008 = `do_emit_pillars <- function(x, tier_widths, cb, title = NULL, first_pillar = NULL, parent_col_idx = NULL, is_focus = FALSE) {
  top_level <- is.null(first_pillar)

  # Only tweaking sub-title, because full title is needed for extra-cols
  sub_title <- title
  if (!is.null(sub_title)) {
    sub_title[-length(sub_title)][parent_col_idx[-1] != 1] <- ""
  }

  pillar_list <- ctl_new_pillar_list(cb$controller, x, width = tier_widths, title = sub_title, first_pillar = first_pillar)

  # Extra columns are known early on, and remain fixed
  extra <- attr(pillar_list, "extra")

  if (length(pillar_list) == 0) {
    emit_extra_cols(extra, x, title, cb)
    # Doesn't fit
    return(NULL)
  }

  # Simple pillar: fit and proceed
  if (isTRUE(attr(pillar_list, "simple"))) {
    pillar <- pillar_list[[1]]

    pillar_title <- pillar[["title"]]
    title_width <- get_width(pillar_title) %||% 0L

    formatted <- pillar_format_parts_2(
      pillar,
      max(tier_widths),
      is_focus,
      cb$on_get_n_abbrev_cols() + 1L
    )
    true_width <- formatted$max_extent
    stopifnot(true_width <= max(tier_widths))

    used <- compute_used_width(tier_widths, true_width)

    if (used$tiers > 0) {
      cb$on_end_tier()
      cb$on_start_tier()
    }

    cb$on_pillar(formatted)

    if (true_width < title_width) {
      cb$on_abbrev_col(format(pillar_title))
    }

    return(used)
  }

  # We can proceed cautiously to the next level if space permits.
  # For each sub-pillar we allow at most as much space so that
  # we can print all first components of all remaining pillars
  # with the minimum width
  min_widths <- map_int(pillar_list, pillar_get_min_width)
  rev <- distribute_pillars_rev(min_widths, tier_widths)
  stopifnot(!anyNA(rev$tier))

  x_pos <- 0L
  tier_pos <- 1L

  # Advance column by column
  for (col in seq_along(pillar_list)) {
    sub_tier_widths <- compute_sub_tier_widths(
      tier_widths, x_pos, tier_pos,
      rev$offset_after[[col]], rev$tier[[col]]
    )
    "!!!!!DEBUG sub_tier_widths"

    # Recurse
    used <- do_emit_pillars(
      x[[col]],
      sub_tier_widths,
      cb,
      c(title, tick_if_needed(names(x)[[col]])),
      pillar_list[[col]],
      c(parent_col_idx, if (!is.null(names(x))) col),
      is_focus
    )
    "!!!!!DEBUG used"

    adv <- advance_pos(x_pos, tier_pos, used)
    x_pos <- adv$x_pos
    tier_pos <- adv$tier_pos

    if (top_level) {
      cb$on_top_level_pillar()
    }
  }

  # We emit late to ensure that extra columns of compound pillars
  # appear before top-level extra columns.
  emit_extra_cols(extra, x, title, cb)

  list(tiers = tier_pos - 1L, width = x_pos)
}`

const rtdal004538Source0012 = `emit_extra_cols <- function(extra, x, title, cb) {
  if (length(extra) == 0) {
    return()
  }

  if (is.numeric(extra)) {
    if (length(extra) == 1) {
      extra <- paste0("[", extra, "]")
    } else {
      extra <- paste0("[", min(extra), ":", max(extra), "]")
    }
    x_extra <- set_names(list(x[1, ]), extra)
  } else {
    extra <- tick_if_needed(extra)
    x_extra <- tick_names_if_needed(x)
  }

  cb$on_extra_cols(x_extra, title, extra)
}`

