const rtdal004550Source0009 = "vec_math.pillar_num <- function(.fn, .x, ...) {\n  \"!!!!DEBUG vec_math(`v(.fn)`)\"\n\n  out <- vec_math_base(.fn, vec_proxy(.x), ...)\n\n  if (is.numeric(out)) {\n    out <- vec_restore(out, .x)\n  }\n\n  out\n}"

const rtdal004550Source0010 = "set_num_opts <- function(x, ...,\n                         sigfig = NULL, digits = NULL,\n                         label = NULL, scale = NULL,\n                         notation = c(\"fit\", \"dec\", \"sci\", \"eng\", \"si\"),\n                         fixed_exponent = NULL,\n                         extra_sigfig = NULL) {\n  check_dots_empty()\n\n  if (missing(notation)) {\n    notation <- NULL\n  } else if (!is.null(notation)) {\n    notation <- arg_match(notation)\n  }\n\n  if (!is.null(fixed_exponent) && !is.null(notation)) {\n    if (fixed_exponent && notation == \"dec\") {\n      abort('Incomatible arguments: `notation = \"dec\"` and `fixed_exponent` given')\n    }\n  }\n\n  if (!is.null(scale) && is.null(label)) {\n    abort(\"Must set `label` if `scale` is provided.\")\n  }\n\n  if (!is.null(digits) && !is.null(extra_sigfig)) {\n    abort(\"Incompatible arguments: `extra_sigfig` and `digits`.\")\n  }\n\n  pillar_attr <- structure(\n    list(\n      sigfig = sigfig,\n      digits = digits,\n      label = label,\n      scale = scale,\n      notation = notation,\n      fixed_exponent = fixed_exponent,\n      extra_sigfig = extra_sigfig\n    ),\n    class = c(\"pillar_num_attr\", \"pillar_vctr_attr\", \"tibble_vec_attr\")\n  )\n  attr(x, \"pillar\") <- pillar_attr\n  x\n}"

const rtdal004550Source0011 = `format.pillar_num_attr <- function(x, ...) {
  notation <- x$notation
  if (is.null(notation)) {
    class <- "pillar_num"
  } else {
    class <- paste0("pillar_num(", notation, ")")
  }

  sigfig <- x$sigfig
  digits <- x$digits
  label <- x$label
  extra_sigfig <- x$extra_sigfig

  if (!is.null(digits)) {
    if (digits >= 0) {
      out <- paste0(class, ":.", digits, "!")
    } else {
      out <- paste0(class, ":.", -digits)
    }
  } else if (!is.null(sigfig)) {
    out <- paste0(class, ":", sigfig)

    if (isTRUE(extra_sigfig)) {
      out <- paste0(out, "*")
    }
  } else if (isTRUE(extra_sigfig)) {
    out <- paste0(class, "*")
  } else {
    out <- class
  }

  if (!is.null(label)) {
    out <- paste0(out, "{", label, "}")
  }

  scale <- x$scale

  if (!is.null(scale)) {
    out <- paste0(out, "*", scale)
  }

  fixed_exponent <- x$fixed_exponent

  if (!is.null(fixed_exponent)) {
    out <- paste0(out, "|", fixed_exponent)
  }

  out
}`

