const rtdal004578Source0004 = `type_sum.default <- function(x) {
  pillar_attr <- attr(x, "pillar", exact = TRUE)

  label <- pillar_attr$label
  if (!is.null(label)) {
    return(I(label))
  }

  if (is.object(x) || vec_is(x)) {
    return(vec_ptype_abbr(x))
  }

  switch(typeof(x),
    builtin = ,
    special = ,
    closure = "fn",
    environment = "env",
    symbol =
      if (is_missing(x)) {
        "missing"
      } else {
        "sym"
      },
    typeof(x)
  )
}`

const rtdal004578Source0005 = `vec_ptype_abbr.pillar_empty_col <- function(x, ...) {
  vec_ptype_abbr(x[[1]])
}`

const rtdal004578Source0007 = `obj_sum.default <- function(x) {
  if (!vec_is(x)) {
    type_sum(x)
  } else {
    abbr <- vec_ptype_abbr(x, suffix_shape = FALSE)

    out <- paste(abbr, size_sum(x))
    if (is.array(x)) {
      short <- paste0(abbr, "[", symbol$ellipsis, "]")
    } else {
      short <- abbr
    }

    structure(out, short = short)
  }
}`

