const rtdal004581Source0001 = `pillar_shaft.pillar_vctr <- function(x, ...) {
  # still seems necessary
  pillar_shaft(unclass(x))
}`

const rtdal004581Source0002 = `vec_ptype_full.pillar_vctr <- function(x, ...) {
  format(attr(x, "pillar", exact = TRUE))
}`

const rtdal004581Source0003 = `print.pillar_vctr <- function(x, ..., max = NULL) {
  if (is.null(max)) {
    max <- getOption("max.print")
  }

  xx <- vec_head(x, max)
  size <- vec_size(x)

  obj_print_header.pillar_vctr(xx, ..., .size = size)
  obj_print_data.pillar_vctr(xx, ..., .size = size)
  obj_print_footer.pillar_vctr(xx, ..., .size = size)
  invisible(x)
}`

const rtdal004581Source0004 = `obj_print_header.pillar_vctr <- function(x, ..., .size) {
  writeLines(paste0("<", vec_ptype_full(x), "[", .size, "]>"))
  pillar_attr <- attr(x, "pillar")
  if (!is.null(pillar_attr$fixed_exponent)) {
    shaft <- pillar_shaft_number_attr(numeric(), pillar_attr)
    type <- attr(shaft, "type")
    if (!is.null(type)) {
      writeLines(paste0("Fixed exponent: ", type[[1]]))
    }
  }
  invisible(x)
}`

const rtdal004581Source0005 = `obj_print_data.pillar_vctr <- function(x, ..., .size) {
  if (length(x) == 0) {
    return(invisible(x))
  }

  # FIXME: base::print.default() can't use color, roll own implementation?
  out <- stats::setNames(ansi_strip(format(x)), names(x))
  print(out, quote = FALSE, max = vec_size(x))
  invisible(x)
}`

const rtdal004581Source0006 = `obj_print_footer.pillar_vctr <- function(x, ..., .size) {
  delta <- .size - vec_size(x)

  if (delta <= 0) {
    return(invisible(x))
  }

  writeLines(style_subtle(pre_dots(paste0("and ", delta, " more"))))
  invisible(x)
}`

const rtdal004581Source0007 = `print.pillar_vctr_attr <- function(x, ...) {
  writeLines(format(x))
  invisible(x)
}`

const rtdal004581Source0008 = `vec_proxy_compare.pillar_vctr <- function(x, ...) {
  vec_data(x)
}`

const rtdal004581Source0009 = `vec_proxy_order.pillar_vctr <- function(x, ...) {
  vec_data(x)
}`

